style.css:
/* Add a playful background with a Flamingo photo */
body {
  background-image: url('https://i.pinimg.com/736x/b0/42/8f/b0428f52d6e1b799cac37012c1a1f646.jpg'); /* Main background image */
  background-size: cover;
  background-repeat: no-repeat;
  background-attachment: fixed;
  color: #ff69b4 !important; /* Flamingo-pink text */
  font-family: 'Comic Sans MS', cursive !important; /* Meme font */
}

/* Add Flamingo-themed header with another image */
header {
  background-image: url('https://i.pinimg.com/736x/28/19/e7/2819e744af61f3ee47e69d598e9ba445.jpg'); /* Header image */
  background-size: cover;
  height: 200px;
  border-bottom: 5px solid #000000 !important; /* Black border */
}

/* Meme-worthy buttons */
button {
  background-color: #ff69b4 !important; /* Bright pink background */
  color: #ffffff !important; /* White text */
  border: 5px solid #000000 !important; /* Black border */
  font-size: 20px !important;
  border-radius: 15px !important; /* Rounded buttons */
  transform: rotate(-5deg); /* Fun tilt */
  box-shadow: 5px 5px #000000 !important; /* Meme shadow */
}

/* Style links with animated effects */
a {
  color: #00ffff !important; /* Aqua link color */
  font-weight: bold !important;
  text-decoration: underline wavy red !important; /* Wavy red underline */
  transition: color 0.3s ease, transform 0.3s ease;
}

a:hover {
  color: #ff4500 !important; /* Flaming orange hover */
  transform: scale(1.1); /* Zoom effect */
}

/* Add Flamingo frames to all images */
img {
  border: 10px solid #ff69b4 !important; /* Pink border */
  border-radius: 20px !important; /* Rounded corners */
  transform: rotate(3deg); /* Tilt for fun */
}

/* Style text headers with a Flamingo vibe */
h1, h2, h3, h4, h5, h6 {
  color: #ff69b4 !important; /* Pink headers */
  text-shadow: 3px 3px #000000 !important; /* Black shadow */
  font-family: 'Impact', sans-serif !important; /* Meme font */
  transform: rotate(-3deg); /* Tilted text */
  background-image: url('https://i.pinimg.com/736x/99/2d/90/992d9061dd4e4cb7990dfac2a00768ac.jpg'); /* Meme-worthy background in headers */
  background-size: contain;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent; /* Makes text see-through */
}

/* Footer with a Flamingo flair */
footer {
  background-image: url('https://i.pinimg.com/736x/de/3c/04/de3c04318142e1b96c1df6fc454ad5c0.jpg'); /* Footer Flamingo */
  background-size: cover;
  height: 150px;
  border-top: 5px solid #000000 !important;
}
